window.kbPageData["views/entry/k-1f93edec2af3853e"] = {"key":"entry/k-1f93edec2af3853e","state":{"route":"entry/k-1f93edec2af3853e"},"node":{"id":"k-1f93edec2af3853e","mode":"k","title":"智慧交通运输管理系统治超","type":"原理与机制","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":["源头称重预警与路面动态检测协同治理货运超载超限"],"qs":["江苏 2024 B类 申论#1"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"申论材料中的C县依托智慧交通运输管理系统，将砂石运输车辆的装车称重预警与道路不停车称重、现场复查相结合，治理货运超载超限。","review":{"definition":"申论材料中的C县依托智慧交通运输管理系统，将砂石运输车辆的装车称重预警与道路不停车称重、现场复查相结合，治理货运超载超限。","explanation":"装车时，平台读取源头企业的称重数据，发现疑似超载便提醒企业和驾驶员现场整改，达标后方可运输。对行驶中的货车，不停车称重筛查疑似超载超限车辆，沿线显示屏提示复检，执法人员接到通知后锁定车辆并在检测点复查。作答可把两道关口概括为加强源头监管和路面管控，并写出提高治超效率、节省驾驶员等待时间的成效。","references":[{"source":"web-098acc6525b85d4b","location":"给定资料2，C县砂石运输案例","quote":"提醒源头企业和车辆驾驶员现场整改"}],"evidence":"提高货运车辆超载超限执法能力，节约时间","disposition":"题内说明","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2024 B类 申论#1":{"paper":"江苏 2024 B类 申论","n":1,"mod":"申论","src":["bed85ff950924671a40c.pdf",4],"asrc":["f75bd8f3e117a96a77ba.pdf",1],"card":"6350a02e4789ef6b2b4386c9","links":[{"id":"k-1f93edec2af3853e","role":"直接考查","why":"概括这一案例需说明装车预警促成出场前整改，路面动态检测支持快速定位和复查。"}]}},"terms":{},"references":{"web-098acc6525b85d4b":{"name":"2024年江苏公务员录用考试《申论》真题（B类，公开转录本）","url":"https://upload.xingguanggongkao.com/admin/20240823/66c80869e0db3.pdf"}},"topics":[],"units":{"k-1f93edec2af3853e":[["江苏 2024 B类 申论#1"]]}};
